import type { MetadataRoute } from "next";

// Lets Android and iOS (Add to Home Screen) install Moneo as a standalone app.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Moneo — Personal Finance Workspace",
    short_name: "Moneo",
    description: "Understand your money, plan decisions, and build reusable financial tools with AI.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0f1011",
    theme_color: "#0f1011",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
      { src: "/icon-512-maskable.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}

// Generates placeholder PWA icons: a lime geometric "M" on graphite (the app's dark palette).
import { deflateSync } from "node:zlib";
import { writeFileSync } from "node:fs";

const BG = [0x0f, 0x10, 0x11];
const FG = [0xcb, 0xf2, 0x6b];
const OUT = process.argv[2];

const crcTable = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
};

// Stroke segments in a 0..1 grid: two stems and two diagonals meeting at the bottom centre.
const SEGMENTS = [
  [[0.27, 0.27], [0.27, 0.73]],
  [[0.73, 0.27], [0.73, 0.73]],
  [[0.27, 0.27], [0.5, 0.6]],
  [[0.73, 0.27], [0.5, 0.6]],
];
const STROKE = 0.1;

const distToSegment = (px, py, [[ax, ay], [bx, by]]) => {
  const dx = bx - ax, dy = by - ay;
  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)));
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
};

// scale < 1 shrinks the glyph toward the centre (used for maskable icons' safe zone).
const render = (size, scale) => {
  const SS = 3; // supersampling per axis for smooth edges
  const raw = Buffer.alloc(size * (size * 3 + 1));
  for (let y = 0; y < size; y++) {
    raw[y * (size * 3 + 1)] = 0; // filter: none
    for (let x = 0; x < size; x++) {
      let hits = 0;
      for (let sy = 0; sy < SS; sy++) for (let sx = 0; sx < SS; sx++) {
        const u = (x + (sx + 0.5) / SS) / size;
        const v = (y + (sy + 0.5) / SS) / size;
        const px = 0.5 + (u - 0.5) / scale, py = 0.5 + (v - 0.5) / scale;
        if (SEGMENTS.some((s) => distToSegment(px, py, s) <= STROKE / 2)) hits++;
      }
      const a = hits / (SS * SS);
      const o = y * (size * 3 + 1) + 1 + x * 3;
      for (let c = 0; c < 3; c++) raw[o + c] = Math.round(BG[c] + (FG[c] - BG[c]) * a);
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // RGB, no alpha (iOS icons must not have transparency)
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
};

const outputs = [
  ["icon-192.png", 192, 1],
  ["icon-512.png", 512, 1],
  ["icon-512-maskable.png", 512, 0.8],
  ["apple-touch-icon.png", 180, 1],
];
for (const [name, size, scale] of outputs) {
  writeFileSync(`${OUT}/${name}`, render(size, scale));
  console.log("wrote", name);
}

